rules.suggestion:
使用Optional、@NonNull注解、Objects.requireNonNull()或显式空值检查。

// 错误示例
public String getUserName(User user) {
    return user.getAddress().getCity().getName(); // 任一环节为null则NPE
}

// 正确示例1 - Optional
public String getUserName(User user) {
    return Optional.ofNullable(user)
        .map(User::getAddress)
        .map(Address::getCity)
        .map(City::getName)
        .orElse("未知");
}

// 正确示例2 - 方法入口校验
public void processOrder(@NonNull Order order) {
    Objects.requireNonNull(order, "order不能为null");
    Objects.requireNonNull(order.getId(), "orderId不能为null");
}

始终使用try-with-resources语句自动关闭资源。

// 错误示例
public String readFile(String path) throws IOException {
    BufferedReader reader = new BufferedReader(new FileReader(path));
    String line = reader.readLine(); // 若此处抛异常，reader不会关闭
    reader.close(); // 可能永远执行不到
    return line;
}

// 正确示例
public String readFile(String path) throws IOException {
    try (BufferedReader reader = new BufferedReader(new FileReader(path))) {
        return reader.readLine();
    } // reader自动关闭，即使发生异常
}

// 数据库连接
public User findUser(Long id) {
    try (Connection conn = dataSource.getConnection();
         PreparedStatement ps = conn.prepareStatement("SELECT * FROM user WHERE id=?")) {
        ps.setLong(1, id);
        try (ResultSet rs = ps.executeQuery()) {
            return rs.next() ? mapUser(rs) : null;
        }
    }
}

将常量或确定非null的值放在equals()左侧，或使用Objects.equals()、StringUtils.equals()。

// 错误示例
if (user.getStatus().equals("ACTIVE")) { ... }
if (user.getRole().equals(Role.ADMIN)) { ... }

// 正确示例1 - 常量在左
if ("ACTIVE".equals(user.getStatus())) { ... }
if (Role.ADMIN.equals(user.getRole())) { ... }

// 正确示例2 - Objects.equals
if (Objects.equals(user.getStatus(), "ACTIVE")) { ... }

// 正确示例3 - 枚举直接用==
if (user.getRole() == Role.ADMIN) { ... }

多线程场景使用ConcurrentHashMap。只读共享使用ImmutableMap或Collections.unmodifiableMap()。

// 错误示例
private Map<String, Object> cache = new HashMap<>();
// 多线程同时调用 cache.put() 导致数据竞争

// 正确示例1 - ConcurrentHashMap
private ConcurrentMap<String, Object> cache = new ConcurrentHashMap<>();

// 正确示例2 - 使用computeIfAbsent原子操作
Object value = cache.computeIfAbsent(key, k -> loadFromDb(k));

// 注意：ConcurrentHashMap不支持null key和null value
// 错误：cache.put(null, value); // 抛NPE
// 错误：cache.put(key, null);   // 抛NPE

使用StringBuilder（单线程）或StringBuffer（多线程），或使用Stream.collect(joining())。

// 错误示例
String result = "";
for (String item : items) {
    result += item + ","; // 每次循环创建新对象
}

// 正确示例1 - StringBuilder
StringBuilder sb = new StringBuilder(items.size() * 16);
for (String item : items) {
    sb.append(item).append(",");
}
String result = sb.toString();

// 正确示例2 - Stream
String result = items.stream().collect(Collectors.joining(","));

// 正确示例3 - StringJoiner
StringJoiner joiner = new StringJoiner(", ");
items.forEach(joiner::add);

使用Java 8+的java.time包（LocalDate、LocalDateTime、DateTimeFormatter），这些都是不可变且线程安全的。

// 错误示例
private static final SimpleDateFormat SDF = new SimpleDateFormat("yyyy-MM-dd");
// 多线程共享SDF导致日期解析错误！

public Date parseDate(String str) throws ParseException {
    return SDF.parse(str); // 并发下可能抛异常或返回错误结果
}

// 正确示例
private static final DateTimeFormatter FORMATTER = 
    DateTimeFormatter.ofPattern("yyyy-MM-dd");

public LocalDate parseDate(String str) {
    return LocalDate.parse(str, FORMATTER); // 线程安全
}

// 如果需要格式化时间戳
public String formatTimestamp(Instant instant) {
    return instant.atZone(ZoneId.of("Asia/Shanghai"))
        .format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
}

重新设计类结构，引入第三方Bean打破循环，或合并紧密耦合的类。

// 错误示例 - 循环依赖
@Service
public class OrderService {
    @Autowired private PaymentService paymentService; // A依赖B
}

@Service
public class PaymentService {
    @Autowired private OrderService orderService; // B依赖A
}

// 正确示例1 - 引入第三方服务
@Service
public class OrderSettlementService {
    @Autowired private OrderRepository orderRepo;
    @Autowired private PaymentRepository paymentRepo;
    // 将互相调用的逻辑提取到这里
}

// 正确示例2 - 事件驱动解耦
@Service
public class OrderService {
    @Autowired private ApplicationEventPublisher eventPublisher;

    public void completeOrder(Order order) {
        orderRepo.update(order);
        eventPublisher.publishEvent(new OrderCompletedEvent(order.getId()));
    }
}

@EventListener
public void onOrderCompleted(OrderCompletedEvent event) {
    paymentService.processPayment(event.getOrderId());
}

将需要事务的方法设为public，或通过注入自身代理来调用。同类方法调用需特别注意。

// 错误示例1 - private方法
@Transactional // 无效！
private void createOrder(OrderDTO dto) { ... }

// 错误示例2 - 同类内部调用
@Service
public class OrderService {
    public void placeOrder(OrderDTO dto) {
        doCreateOrder(dto); // 内部调用，@Transactional无效！
    }

    @Transactional // 无效！因为是从同类内部调用的
    public void doCreateOrder(OrderDTO dto) {
        orderRepo.save(dto);
        paymentRepo.deduct(dto);
    }
}

// 正确示例 - 方法改为public，从外部调用
@Service
public class OrderService {
    @Autowired private OrderService self; // 注入自身代理

    public void placeOrder(OrderDTO dto) {
        self.doCreateOrder(dto); // 通过代理调用，事务生效
    }

    @Transactional
    public void doCreateOrder(OrderDTO dto) {
        orderRepo.save(dto);
        paymentRepo.deduct(dto);
    }
}

使用@EntityGraph或JOIN FETCH显式预加载关联数据。或使用@BatchSize设置批量加载。

// 错误示例
List<Order> orders = orderRepository.findAll(); // 1次SQL
for (Order o : orders) {
    o.getItems().size(); // 每个order触发1次SQL，共N次
}

// 正确示例1 - @EntityGraph
@EntityGraph(attributePaths = {"items", "customer"})
@Query("SELECT o FROM Order o")
List<Order> findAllWithDetails();

// 正确示例2 - JOIN FETCH
@Query("SELECT o FROM Order o JOIN FETCH o.items i JOIN FETCH o.customer c")
List<Order> findAllWithDetails();

// 正确示例3 - @BatchSize减少查询次数
@OneToMany(mappedBy = "order", fetch = FetchType.LAZY)
@BatchSize(size = 50) // 每50个一批查询
private List<OrderItem> items;

禁止使用enableDefaultTyping()。使用@JsonTypeInfo时限定允许的类型白名单。升级Jackson到最新版本。

// 错误示例 - 极度危险
ObjectMapper mapper = new ObjectMapper();
mapper.enableDefaultTyping(); // 允许反序列化任意类！
Object obj = mapper.readValue(userInput, Object.class); // RCE！

// 错误示例2 - 未限制子类型
@JsonTypeInfo(use = JsonTypeInfo.Id.CLASS) // 允许任意类！
class Message { ... }

// 正确示例 - 使用白名单限制
@JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.PROPERTY)
@JsonSubTypes({
    @JsonSubTypes.Type(value = TextMessage.class, name = "text"),
    @JsonSubTypes.Type(value = ImageMessage.class, name = "image")
})
class Message { ... }

// 正确示例2 - 禁用多态类型处理
ObjectMapper mapper = new ObjectMapper();
// 不调用 enableDefaultTyping()
mapper.deactivateDefaultTyping();

使用SLF4J + Logback/Log4j2日志框架，配合MDC输出上下文信息。

// 错误示例
System.out.println("User " + userId + " logged in at " + new Date());

// 正确示例
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Slf4j // Lombok注解
public class UserService {
    // 或手动声明: private static final Logger log = LoggerFactory.getLogger(UserService.class);

    public void login(Long userId) {
        log.info("User logged in, userId={}", userId); // 占位符，不拼接字符串
        log.debug("Login details: {}", () -> getExpensiveDebugInfo()); // 延迟求值
    }
}

至少记录日志，必要时向上抛出或转换为业务异常。

// 错误示例1 - 空catch块
try {
    riskyOperation();
} catch (Exception e) {
    // 什么都不做
}

// 错误示例2 - 只打印堆栈
try {
    riskyOperation();
} catch (Exception e) {
    e.printStackTrace(); // 输出到System.err，生产环境不可控
}

// 正确示例
try {
    riskyOperation();
} catch (BusinessException e) {
    log.warn("业务处理失败, orderId={}, reason={}", orderId, e.getMessage());
    throw new OrderException("订单处理失败", e);
} catch (Exception e) {
    log.error("系统异常, orderId={}", orderId, e); // 记录完整堆栈
    throw new SystemException("系统内部错误", e);
}

使用equals()比较Integer值，或使用基本类型int进行比较。先做null检查或使用Objects.equals()。

// 错误示例
Integer a = 200;
Integer b = 200;
if (a == b) { ... } // false! 超出缓存范围

Integer x = 100;
Integer y = 100;
if (x == y) { ... } // true! 在缓存范围内，产生误导

// 正确示例1 - equals()
if (Objects.equals(a, b)) { ... }

// 正确示例2 - 拆箱为int
if (a != null && b != null && a.intValue() == b.intValue()) { ... }

// 正确示例3 - 业务代码中尽量使用基本类型
int count = getCount(); // 用int而非Integer
if (count == 200) { ... }

使用BigDecimal.valueOf(double)或new BigDecimal(String)。

// 错误示例
BigDecimal price = new BigDecimal(0.1); // 0.10000000000000000555...
BigDecimal total = new BigDecimal(19.99); // 19.989999999999998...

// 正确示例1 - valueOf
BigDecimal price = BigDecimal.valueOf(0.1); // 精确的0.1
BigDecimal total = BigDecimal.valueOf(19.99); // 精确的19.99

// 正确示例2 - String构造器
BigDecimal price = new BigDecimal("0.1"); // 精确的0.1
BigDecimal total = new BigDecimal("19.99");

// 正确示例3 - 常量
BigDecimal ZERO = BigDecimal.ZERO;
BigDecimal HUNDRED = new BigDecimal("100");

需要可变列表时，使用new ArrayList<>(Arrays.asList(...))或List.of()包装。

// 错误示例
List<String> list = Arrays.asList("a", "b", "c");
list.add("d"); // UnsupportedOperationException!
list.remove("a"); // UnsupportedOperationException!

// 正确示例1 - 包装为ArrayList
List<String> list = new ArrayList<>(Arrays.asList("a", "b", "c"));
list.add("d"); // OK

// 正确示例2 - Java 9+
List<String> list = new ArrayList<>(List.of("a", "b", "c"));

// 正确示例3 - Stream
List<String> list = Stream.of("a", "b", "c").collect(Collectors.toList());

// 注意：Arrays.asList的修改会影响原数组
String[] arr = {"a", "b"};
List<String> list = Arrays.asList(arr);
list.set(0, "x"); // arr[0]也变成了"x"！

使用Stream的归约操作（collect、reduce）代替外部状态修改。

// 错误示例 - 在Stream中修改外部集合
List<String> result = new ArrayList<>();
names.stream()
    .filter(n -> n.startsWith("A"))
    .map(n -> { result.add(n.toUpperCase()); return n; }) // 副作用！
    .collect(Collectors.toList());

// 正确示例
List<String> result = names.stream()
    .filter(n -> n.startsWith("A"))
    .map(String::toUpperCase)
    .collect(Collectors.toList());

// 错误示例2 - 在forEach中修改共享变量
AtomicInteger counter = new AtomicInteger(0);
list.stream().forEach(item -> {
    if (item.isValid()) counter.incrementAndGet(); // 应避免
});

// 正确示例
long count = list.stream().filter(Item::isValid).count();

Optional仅用于方法返回值。字段直接允许null或使用默认值，参数使用@Nullable注解或方法重载。

// 错误示例
public class User {
    private Optional<String> phone; // 不应使用Optional作为字段

    public void setPhone(Optional<String> phone) { ... } // 不应作为参数
}

// 正确示例
public class User {
    private String phone; // 允许null或使用默认值

    public Optional<String> getPhone() {
        return Optional.ofNullable(phone); // 仅在getter返回时包装
    }

    public void setPhone(String phone) {
        this.phone = phone;
    }
}

// Optional正确用法 - 方法返回值
public Optional<User> findById(Long id) {
    return Optional.ofNullable(userRepo.findById(id));
}

// 禁止：Optional作为集合元素
List<Optional<String>> list; // 禁止！

将synchronized块缩小到仅包含共享可变状态操作的代码段。IO操作、日志记录等应移出同步块。

// 错误示例 - synchronized范围过大
public synchronized void processOrder(Order order) {
    // 1. 验证订单（不需要同步）
    validate(order);
    // 2. 调用外部API（不需要同步且很慢）
    String token = authService.getToken();
    httpClient.call(token, order);
    // 3. 更新共享状态（真正需要同步的部分）
    orderCount++;
    orderMap.put(order.getId(), order);
    // 4. 记录日志（不需要同步）
    log.info("Order processed: {}", order.getId());
}

// 正确示例 - 精确同步
public void processOrder(Order order) {
    validate(order);
    String token = authService.getToken();
    httpClient.call(token, order);

    synchronized (this) { // 仅同步共享状态操作
        orderCount++;
        orderMap.put(order.getId(), order);
    }

    log.info("Order processed: {}", order.getId());
}

始终在finally块中调用ThreadLocal.remove()。使用try-finally确保清理。

// 错误示例 - 未清理ThreadLocal
public class UserContext {
    private static final ThreadLocal<User> CURRENT_USER = new ThreadLocal<>();

    public static void set(User user) {
        CURRENT_USER.set(user);
    }

    public static User get() {
        return CURRENT_USER.get(); // 可能读到其他用户的脏数据！
    }
    // 没有remove方法！
}

// 正确示例 - Filter中确保清理
public class UserContextFilter implements Filter {
    @Override
    public void doFilter(ServletRequest req, ServletResponse resp, FilterChain chain) 
            throws IOException, ServletException {
        try {
            UserContext.set(extractUser(req));
            chain.doFilter(req, resp);
        } finally {
            UserContext.remove(); // 必须在finally中清理
        }
    }
}

public class UserContext {
    private static final ThreadLocal<User> CURRENT_USER = new ThreadLocal<>();

    public static void set(User user) { CURRENT_USER.set(user); }
    public static User get() { return CURRENT_USER.get(); }
    public static void remove() { CURRENT_USER.remove(); } // 提供清理方法
}
